DROP TRIGGER IF EXISTS trg_after_insert_tbltliveuser;//
CREATE TRIGGER `trg_after_insert_tbltliveuser` AFTER INSERT ON `tbltliveuser` FOR EACH ROW BEGIN DECLARE plan_name VARCHAR(500) DEFAULT ''; DECLARE Acct_status_type VARCHAR(500) DEFAULT 'Start';
SELECT pp.NAME INTO plan_name FROM tblmpostpaidplan pp WHERE pp.POSTPAIDPLANID = (SELECT planid FROM savbillradius.tblcustquotadtls tcq WHERE custid = ( SELECT tc.custid FROM tblcustomers tc WHERE tc.username = NEW.userName ) ORDER BY tcq.quotadtlsid DESC LIMIT 1);
INSERT INTO tblmprocesscdr ( USERNAME, SESSIONID, FRAMEDIPADDRESS, NASIPADDRESS, MACADDRESS, NASPORTID, FRAMED_IPV6_ADDRESS, FRAMED_INTERFACE_ID, DELEGATED_IPV6_PREFIX, STARTTIME, ENDTIME, REQUESTTYPE, AGGREGATEKEY, SESSIONAUTHRULE, UPLOAD, DOWNLOAD, TOTAL, CDRTIME ) VALUES ( NEW.userName, NEW.AcctSessionId, NEW.FramedIPAddress, NEW.NASIPAddress, REPLACE(NEW.CallingStationId, '-', ':'), NEW.NASPort, NEW.framedipv6address, ( SELECT GROUP_CONCAT(SUBSTRING(REPLACE(NEW.FramedInterfaceId, ':', ''), (n * 2) + 1, 2) SEPARATOR ':') FROM ( SELECT @rownum := @rownum + 1 AS n FROM (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) t1, (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) t2, (SELECT @rownum := -1) r ) numbers WHERE (n * 2) < LENGTH(REPLACE(NEW.FramedInterfaceId, ':', '')) ) , NEW.DelegatedIPv6Prefix, NEW.createdate, NEW.lastmodificationdate, IFNULL(NEW.AcctStatusType, 'Start'), "Default Service", CONCAT(plan_name, "##", "TOTAL_QoS_Profile", "#", CASE WHEN NEW.isthrottlespeed THEN '1' ELSE '0' END),0,0,0,0 ); END;//

DROP TRIGGER IF EXISTS trg_after_insert_tbltacctcdr;// CREATE TRIGGER `trg_after_insert_tbltacctcdr` AFTER INSERT ON `tbltacctcdr` FOR EACH ROW BEGIN DECLARE plan_name VARCHAR(500) DEFAULT ''; DECLARE total_upload BIGINT DEFAULT 0; DECLARE total_download BIGINT DEFAULT 0; DECLARE total_sum BIGINT DEFAULT 0; DECLARE total_session_time BIGINT DEFAULT 0; IF NEW.custid != 0 THEN SELECT pp.NAME INTO plan_name FROM tblmpostpaidplan pp WHERE pp.POSTPAIDPLANID = (SELECT planid FROM tblcustquotadtls tcq WHERE custid = ( SELECT tc.custid FROM tblcustomers tc WHERE tc.username = NEW.userName ) ORDER BY tcq.quotadtlsid DESC LIMIT 1);
SELECT IFNULL(SUM(UPLOAD), 0), IFNULL(SUM(DOWNLOAD), 0), IFNULL(SUM(TOTAL), 0), IFNULL(SUM(CDRTIME), 0) INTO total_upload, total_download, total_sum, total_session_time FROM tblmprocesscdr WHERE SESSIONID = NEW.AcctSessionId;
INSERT INTO tblmprocesscdr ( USERNAME, SESSIONID, FRAMEDIPADDRESS, NASIPADDRESS, MACADDRESS, NASPORTID, FRAMED_IPV6_ADDRESS, AGGREGATEKEY, FRAMED_INTERFACE_ID, DELEGATED_IPV6_PREFIX, UPLOAD, DOWNLOAD, TOTAL, CDRTIME, STARTTIME, ENDTIME, REQUESTTYPE, SESSIONAUTHRULE ) VALUES ( NEW.userName, NEW.AcctSessionId, NEW.FramedIPAddress, NEW.NASIPAddress, REPLACE(NEW.CallingStationId, '-', ':'), NEW.NASPort, NEW.framedipv6address, "Default Service", ( SELECT GROUP_CONCAT(SUBSTRING(REPLACE(NEW.FramedInterfaceId, ':', ''), (n * 2) + 1, 2) SEPARATOR ':') FROM ( SELECT @rownum := @rownum + 1 AS n FROM (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) t1, (SELECT 0 UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) t2, (SELECT @rownum := -1) r ) numbers WHERE (n * 2) < LENGTH(REPLACE(NEW.FramedInterfaceId, ':', '')) ), NEW.DelegatedIPv6Prefix,
NEW.AcctInputOctets - total_upload, NEW.AcctOutputOctets - total_download , (NEW.AcctInputOctets + NEW.AcctOutputOctets) - total_sum, NEW.AcctSessionTime - total_session_time, NEW.createdate, DATE_SUB(NOW(), INTERVAL (NEW.AcctSessionTime) SECOND), IFNULL(NEW.AcctStatusType, 'Stop'), CONCAT(plan_name, "##", "TOTAL_QoS_Profile", "#",0) ); END IF; END;//

DROP PROCEDURE IF EXISTS insert_vlan_mappings_from_management;//

CREATE PROCEDURE insert_vlan_mappings_from_management()
BEGIN
DECLARE done INT DEFAULT FALSE;
DECLARE next_validationmappingid INT;
DECLARE v_VLANID INT;
DECLARE v_CIRCUIT_TYPE VARCHAR(255);
DECLARE v_NAS_PORT_ID_2 VARCHAR(255);
DECLARE v_NAS_PORT_ID_3 VARCHAR(255);
DECLARE v_NAS_PORT_ID_4 VARCHAR(255);
DECLARE v_NAS_PORT_ID_5 VARCHAR(255);
DECLARE v_exists_1 INT;
DECLARE v_exists_2 INT;
DECLARE v_final_regex_value VARCHAR(500);

DECLARE cur CURSOR FOR
SELECT VLANID, CIRCUIT_TYPE, NAS_PORT_ID_2, NAS_PORT_ID_3, NAS_PORT_ID_4, NAS_PORT_ID_5
FROM savbillradius.tblmvlanmanagement;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

OPEN cur;
read_loop: LOOP
FETCH cur INTO v_VLANID, v_CIRCUIT_TYPE, v_NAS_PORT_ID_2, v_NAS_PORT_ID_3, v_NAS_PORT_ID_4, v_NAS_PORT_ID_5;
IF done THEN
LEAVE read_loop;
END IF;

SELECT COUNT(*) INTO v_exists_1
FROM savbillradius.tblmvlanvalidationmapping
WHERE VLANID = v_VLANID AND REGEX = 'REGEX{\\b(pppoe|clips)\\b,{PROFILE{vlan.CIRCUIT_TYPE}}}';

IF v_exists_1 > 0 THEN
UPDATE savbillradius.tblmvlanvalidationmapping
SET REGEXVALUE = v_CIRCUIT_TYPE
WHERE VLANID = v_VLANID
AND REGEX = 'REGEX{\\b(pppoe|clips)\\b,{PROFILE{vlan.CIRCUIT_TYPE}}}';
ELSE
SELECT COALESCE(MAX(VALIDATIONMAPPINGID), 0) + 1 INTO next_validationmappingid
FROM savbillradius.tblmvlanvalidationmapping;

INSERT INTO savbillradius.tblmvlanvalidationmapping
(VALIDATIONMAPPINGID, VLANID, RADIUS_ATTRIBUTE, REGEX, REGEXVALUE)
VALUES
(next_validationmappingid, v_VLANID, 'NAS-Port-Id',
'REGEX{\\b(pppoe|clips)\\b,{PROFILE{vlan.CIRCUIT_TYPE}}}', v_CIRCUIT_TYPE);
END IF;

-- Check if second regex pattern exists
SELECT COUNT(*) INTO v_exists_2
FROM savbillradius.tblmvlanvalidationmapping
WHERE VLANID = v_VLANID
AND REGEX LIKE '{EXP{MERGE%}';




IF v_NAS_PORT_ID_5 IS NOT NULL THEN
SET v_final_regex_value = CONCAT('CONTAINS{REQ{NAS-Port-Id},', v_NAS_PORT_ID_2, ' ',v_NAS_PORT_ID_3,' ', v_NAS_PORT_ID_4, ':', v_NAS_PORT_ID_5, '}');
ELSE
SET v_final_regex_value = CONCAT('CONTAINS{REQ{NAS-Port-Id},', v_NAS_PORT_ID_2,' ', v_NAS_PORT_ID_3,' ', v_NAS_PORT_ID_4, ':}');
END IF;

-- Update or insert based on existence
IF v_exists_2 > 0 THEN
UPDATE savbillradius.tblmvlanvalidationmapping
SET REGEXVALUE = v_final_regex_value
WHERE VLANID = v_VLANID
AND REGEX LIKE '{EXP{MERGE%}';
ELSE
SET next_validationmappingid = next_validationmappingid + 1;

INSERT INTO savbillradius.tblmvlanvalidationmapping
(VALIDATIONMAPPINGID, VLANID, RADIUS_ATTRIBUTE, REGEX, REGEXVALUE)
VALUES
(next_validationmappingid, v_VLANID, 'NAS-Port-Id',
'{EXP{MERGE{PROFILE{vlan.NAS_PORT_ID_2}},MERGE{ },MERGE{PROFILE{vlan.NAS_PORT_ID_3}},MERGE{ },MERGE{PROFILE{vlan.NAS_PORT_ID_4}},MERGE{:},MERGE{PROFILE{vlan.NAS_PORT_ID_5}}}}',
v_final_regex_value);
END IF;
END LOOP;

CLOSE cur;
END //
